from collections import deque
def fill_enclosed(grid, fill=7):
    """Fill every enclosed region of the background color (cells of the background not reachable from the border) with the fill color."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and grid[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    return [[fill if grid[i][j]==bg and not seen[i][j] else v for j,v in enumerate(row)] for i,row in enumerate(grid)]

